import { Typography, Box, Grid, Skeleton } from '@mui/material';
import { alpha } from '@mui/material/styles';
import {
  IProductStockAlertDetails,
  ISalesProductCategoryDetails,
  ILoyalityDetails,
  IloyalityDetailsItem,
} from '../../../core/Interface/dashboard.interface';
import StockCountTable from './stockCountTable';
import SalesCountTable from './SalesCountTable';
import LoyalityDetailTable from './LoyalityDetailTable';
import * as React from 'react';

interface TablePanelsProps {
  isLoading: boolean;
  showProductAlert: boolean;
  showTrendingProduct: boolean;
  showLoyality: boolean;
  productStockAlertDetails?: IProductStockAlertDetails;
  salesProductCategoryDetails?: ISalesProductCategoryDetails;
  loyalityDetails?: ILoyalityDetails;
  filteredLoyalityList: IloyalityDetailsItem[];
}

/* -------------------- STYLES -------------------- */

const titleSx = {
  fontSize: '0.72rem',
  textTransform: 'uppercase',
  letterSpacing: '0.14em',
  color: alpha('#64748b', 0.6),
  mb: 0.5,
};

const mainTitleSx = {
  fontSize: { xs: '1rem', md: '1.15rem' },
  fontWeight: 700,
  color: '#142352',
};

const baseCardSx = {
  width: '100%',
  display: 'flex',
  flexDirection: 'column',
  p: 2,
  borderRadius: 3,
  minHeight: 360,
};

/* -------------------- BACKGROUNDS -------------------- */

const cards = {
  inventory: {
    background:
      'linear-gradient(135deg, rgba(37,99,235,0.06), rgba(255,255,255,0.9))',
    border: '1px solid rgba(37,99,235,0.08)',
    chip: '#2563EB',
  },
  trending: {
    background:
      'linear-gradient(135deg, rgba(16,185,129,0.06), rgba(255,255,255,0.9))',
    border: '1px solid rgba(16,185,129,0.08)',
    chip: '#10B981',
  },
  loyalty: {
    background:
      'linear-gradient(135deg, rgba(245,158,11,0.06), rgba(255,255,255,0.9))',
    border: '1px solid rgba(245,158,11,0.1)',
    chip: '#F59E0B',
  },
};

/* -------------------- COMPONENT -------------------- */

const TablePanels = ({
  isLoading,
  showProductAlert,
  showTrendingProduct,
  showLoyality,
  productStockAlertDetails,
  salesProductCategoryDetails,
  loyalityDetails,
  filteredLoyalityList,
}: TablePanelsProps) => {
  return (
    <Grid
      alignItems="stretch"
      container
      spacing={2}
      sx={{ mb: 2 }}
    >

      {/* INVENTORY */}
      {showProductAlert && (
        <Grid
          item
          xs={12}
          sm={6}
          md={4}
          sx={{ display: 'flex' }}
        >
          <Box sx={{ ...baseCardSx, ...cards.inventory }}>

            <Box>
              <Typography sx={titleSx}>Inventory Alerts</Typography>
              <Typography sx={mainTitleSx}>
                {productStockAlertDetails?.title}
              </Typography>
            </Box>

            <Box sx={{ flex: 1, mt: 2 }}>
              {isLoading ? (
                <Skeleton
                  height={280}
                  variant="rectangular"
                />
              ) : (
                productStockAlertDetails && (
                  <StockCountTable
                    data={productStockAlertDetails.data}
                    title=""
                  />
                )
              )}
            </Box>
          </Box>
        </Grid>
      )}

      {/* TRENDING */}
      {showTrendingProduct && (
        <Grid
          item
          xs={12}
          sm={6}
          md={4}
          sx={{ display: 'flex' }}
        >
          <Box sx={{ ...baseCardSx, ...cards.trending }}>

            <Box>
              <Typography sx={titleSx}>Top Products</Typography>
              <Typography sx={mainTitleSx}>
                {salesProductCategoryDetails?.title}
              </Typography>
            </Box>

            <Box sx={{ flex: 1, mt: 2 }}>
              {isLoading ? (
                <Skeleton
                  height={280}
                  variant="rectangular"
                />
              ) : (
                salesProductCategoryDetails && (
                  <SalesCountTable
                    data={salesProductCategoryDetails.data}
                    title=""
                  />
                )
              )}
            </Box>
          </Box>
        </Grid>
      )}

      {/* LOYALTY */}
      {showLoyality && (
        <Grid
          item
          xs={12}
          sm={6}
          md={4}
          sx={{ display: 'flex' }}
        >
          <Box sx={{ ...baseCardSx, ...cards.loyalty }}>

            <Box>
              <Typography sx={titleSx}>Loyalty Program</Typography>
              <Typography sx={mainTitleSx}>
                {loyalityDetails?.title}
              </Typography>
            </Box>

            <Box sx={{ flex: 1, mt: 2 }}>
              {isLoading ? (
                <Skeleton
                  height={280}
                  variant="rectangular"
                />
              ) : (
                loyalityDetails && (
                  <LoyalityDetailTable
                    data={filteredLoyalityList}
                    title=""
                  />
                )
              )}
            </Box>
          </Box>
        </Grid>
      )}

    </Grid>
  );
};

export default TablePanels;