import { Grid, Typography, Box, Chip, Skeleton } from '@mui/material';
import { alpha } from '@mui/material/styles';
import {
  ISplineCharts,
  IPieChart,
} from '../../../core/Interface/dashboard.interface';
import { appColors } from '../../../theme/appColors';
import SplineCharts from './SplineCharts';
import PieChart from './PieChart';
import * as React from 'react';

export const chartPanelCardSx = {
  borderRadius: 2,
  border: `1px solid ${alpha('#d8e1ef', 0.9)}`,
  background:
    'linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(245,248,255,0.96) 100%)',
  boxShadow: '0 20px 45px rgba(15, 23, 42, 0.08)',
};

const titleSx = {
  fontSize: '0.72rem',
  textTransform: 'uppercase',
  letterSpacing: '0.14em',
  color: alpha(appColors.blueGreyishLight[80], 0.58),
  mb: 0.5,
};

const mainTitleSx = {
  fontSize: { xs: '1rem', md: '1.15rem' },
  fontWeight: 700,
  color: '#142352',
};

const subTitleSx = {
  mt: 0.4,
  color: alpha(appColors.blueGreyishLight[80], 0.72),
  fontSize: '0.85rem',
};

const cardGradientLeft =
  'linear-gradient(135deg, rgba(37,99,235,0.06), rgba(99,102,241,0.04), rgba(255,255,255,0.9))';

const cardGradientRight =
  'linear-gradient(135deg, rgba(245,158,11,0.06), rgba(34,197,94,0.05), rgba(255,255,255,0.9))';

  interface ChartPanelsProps {
  isLoading: boolean;
  showWeeklySale: boolean;
  showCategory: boolean;
  dailySalesDetails?: ISplineCharts;
  xAxisData?: string[];
  yAxisData?: number[];
  categoryProductCount?: IPieChart;
  transformedData?: (string | number)[][];
}

const ChartPanels = ({
  isLoading,
  dailySalesDetails,
  xAxisData,
  yAxisData,
  categoryProductCount,
  transformedData,
}: ChartPanelsProps) => {
  return (
    <Grid
      alignItems="stretch"
      container
      spacing={2}
      sx={{ mb: 2 }}
    >
      
      {/* LEFT */}
      <Grid
        item
        md={6}
        sx={{ display: 'flex' }}
        xs={12}
      >
        <Box
          sx={{
            width: '100%',
            display: 'flex',
            flexDirection: 'column',
            borderRadius: 3,
            p: 2,
            background: cardGradientLeft,
            border: '1px solid rgba(120, 79, 255, 0.08)',
            minHeight: 380,
            transition: 'all 0.25s ease'
          }}
        >
          <Box sx={{ position: 'relative' }}>
            <Box>
              <Typography sx={titleSx}>Sales Trend</Typography>
              <Typography sx={mainTitleSx}>
                {dailySalesDetails?.title}
              </Typography>
              <Typography sx={subTitleSx}>
                {dailySalesDetails?.subTitle}
              </Typography>
            </Box>

            <Chip
              label={`${xAxisData?.length || 0} days`}
              size="small"
              sx={{
                position: 'absolute',
                top: 0,
                right: 0,
                bgcolor: alpha('#2563EB', 0.10),
                color: '#2563EB',
                fontWeight: 700,
                borderRadius: 1,
              }}
            />
          </Box>

          <Box sx={{ flex: 1, width: '100%', mt: 2 }}>
            {isLoading ? (
              <Skeleton
                height={320}
                variant="rectangular"
                width="100%"
              />
            ) : (
              <SplineCharts
                xAxisData={xAxisData ?? []}
                xAxisTittle={dailySalesDetails?.xAxisDescription || ''}
                yAxisData={yAxisData ?? []}
                yAxisTitle={dailySalesDetails?.yAxisDescription || ''}
              />
            )}
          </Box>
        </Box>
      </Grid>

      {/* RIGHT */}
      <Grid
        item
        md={6}
        sx={{ display: 'flex' }}
        xs={12}
      >
        <Box
          sx={{
            width: '100%',
            display: 'flex',
            flexDirection: 'column',
            borderRadius: 3,
            p: 2,
            background: cardGradientRight,
            border: '1px solid rgba(210, 136, 7, 0.1)',
            minHeight: 380,
          }}
        >
          <Box sx={{ position: 'relative' }}>
            <Box>
              <Typography sx={titleSx}>Category Breakdown</Typography>
              <Typography sx={mainTitleSx}>
                {categoryProductCount?.title}
              </Typography>
              <Typography sx={subTitleSx}>
                {categoryProductCount?.subTitle}
              </Typography>
            </Box>

            <Chip
              label={`${xAxisData?.length || 0} days`}
              size="small"
              sx={{
                position: 'absolute',
                top: 0,
                right: 0,
                bgcolor: alpha('#F59E0B', 0.12),
                color: '#F59E0B',
                fontWeight: 700,
                borderRadius: 1,
              }}
            />
          </Box>

          <Box sx={{ flex: 1, width: '100%', mt: 2 }}>
            {isLoading ? (
              <Skeleton
                height={320}
                variant="rectangular"
                width="100%"
              />
            ) : (
              <PieChart
                chartDescription={
                  categoryProductCount?.chartDescription || ''
                }
                data={transformedData ?? []}
              />
            )}
          </Box>
        </Box>
      </Grid>
    </Grid>
  );
};

export default ChartPanels;