import React from 'react';
import { appColors } from '../../../theme/appColors';
import HighchartsReact from 'highcharts-react-official';
import Highcharts from 'highcharts';

interface ISplineCharts {
  xAxisTittle: string;
  yAxisTitle: string;
  xAxisData: string[];
  yAxisData: number[];
}

const SplineCharts = (props: ISplineCharts) => {
  const { xAxisTittle, yAxisTitle, xAxisData, yAxisData } = props;

  return (
    <HighchartsReact
      containerProps={{ style: { width: '100%' } }}
      highcharts={Highcharts}
      options={{
        chart: {
          type: 'spline',
          backgroundColor: 'transparent',
          reflow: true,
          style: { fontFamily: 'verlag' },
        },
        title: { text: '' },
        subtitle: { text: '' },
        xAxis: {
          reversed: false,
          title: {
            enabled: true,
            text: xAxisTittle,
            style: {
              color: appColors.forestGreen[80],
              fontWeight: 'bold',
              fontFamily: 'verlag',
            },
          },
          labels: {
            style: { color: appColors.reflexBlue[80], fontFamily: 'verlag' },
          },
          showLastLabel: true,
          categories: xAxisData,
        },
        yAxis: {
          title: {
            text: yAxisTitle,
            style: {
              color: appColors.forestGreen[80],
              fontWeight: 'bold',
              fontFamily: 'verlag',
            },
          },
          labels: {
            format: '{value}',
            style: { color: appColors.reflexBlue[80], fontFamily: 'verlag' },
          },
        },
        credits: { enabled: false },
        legend: { enabled: false },
        tooltip: {
          headerFormat: `<b style="color: ${appColors.carmineRed[90]}">{series.name}</b><br/>`,
          pointFormat: `<span style="color: ${appColors.carmineRed[60]}">{point.category}: {point.y}</span>`,
          backgroundColor: appColors.persianBlue[20],
        },
        plotOptions: {
          spline: { marker: { enable: false } },
        },
        accessibility: { enabled: false },
        series: [{ name: 'Sales', data: yAxisData }],
      }}
    />
  );
};

export default React.memo(SplineCharts);
