import { Box, Typography, TextField, InputAdornment } from '@mui/material';
import React from 'react';
import SearchIcon from '@mui/icons-material/Search';
import { alpha } from '@mui/material/styles';

interface ILoyalityDetailsItem {
  mobile: string;
  name: string;
  points: string;
}

interface ILoyalityDetails {
  title: string;
  data: ILoyalityDetailsItem[];
}

/* -------------------- STYLES -------------------- */

const titleSx = {
  fontSize: '0.72rem',
  textTransform: 'uppercase',
  letterSpacing: '0.14em',
  color: alpha('#64748b', 0.6),
  mb: 0.5,
};

const headerTitleSx = {
  fontSize: '1rem',
  fontWeight: 700,
  color: '#142352',
};

const rowSx = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  px: 1.5,
  py: 1.2,
  borderRadius: 2,
  mb: 0.8,
  background: 'rgba(255,255,255,0.75)',
  border: '1px solid rgba(226,232,240,0.8)',
  transition: 'all 0.2s ease',
  '&:hover': {
    background: 'rgba(255,255,255,1)',
    transform: 'translateY(-1px)',
  },
};

const LoyalityDetailTable = ({ title, data }: ILoyalityDetails) => {
  const [searchQuery, setSearchQuery] = React.useState('');

  const filteredData = React.useMemo(() => {
    if (!searchQuery) return data;

    const q = searchQuery.toLowerCase();

    return data.filter(
      (item) =>
        item.mobile.toLowerCase().includes(q) ||
        item.name.toLowerCase().includes(q)
    );
  }, [data, searchQuery]);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>

      {/* HEADER */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
          justifyContent: 'space-between',
          alignItems: { xs: 'flex-start', sm: 'center' },
          gap: 1.5,
          pb: 1.5,
          borderBottom: '1px solid rgba(226,232,240,0.9)',
        }}
      >
        <Box>
          <Typography sx={titleSx}>Loyalty</Typography>
          <Typography sx={headerTitleSx}>{title}</Typography>
        </Box>

        <TextField
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon fontSize="small" />
              </InputAdornment>
            ),
          }}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search mobile or name"
          size="small"
          sx={{
            width: { xs: '100%', sm: 260 },
            '& .MuiOutlinedInput-root': {
              borderRadius: 2,
              background: 'rgba(255,255,255,0.8)',
            },
          }}
        />
      </Box>

      {/* BODY */}
      <Box
        sx={{
          mt: 1.5,
          maxHeight: 320,
          overflowY: 'auto',
          pr: 0.5,
        }}
      >
        {filteredData.map((item, index) => (
          <Box
            key={index}
            sx={rowSx}
          >

            {/* LEFT */}
            <Box>
              <Typography
                sx={{
                  fontSize: '0.9rem',
                  fontWeight: 600,
                  color: '#0f172a',
                }}
              >
                {item.mobile}
              </Typography>

              <Typography
                sx={{
                  fontSize: '0.75rem',
                  color: alpha('#64748b', 0.8),
                }}
              >
                {item.name}
              </Typography>
            </Box>

            {/* RIGHT */}
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                sx={{
                  fontSize: '1rem',
                  fontWeight: 700,
                  color: '#f59e0b',
                }}
              >
                {item.points}
              </Typography>

              <Typography
                sx={{
                  fontSize: '0.75rem',
                  color: alpha('#64748b', 0.8),
                }}
              >
                Points
              </Typography>
            </Box>

          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default React.memo(LoyalityDetailTable);